window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58a642b11a613701"]={"versions": [{"id": "FIG-58a642b11a613701", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation der Dokumentationsstrukturen innerhalb des <em>AUTOSAR Generic Structure Template</em> (TPS_GenericStructureTemplate, Kapitel 9 <em>Documentation</em>). Das Metamodell definiert die standardisierte ARXML-Repräsentation von Listenstrukturen (<code>List</code>, <code>LabeledList</code>, <code>DefList</code>) innerhalb von Dokumentationsblöcken (<code>DocumentationBlock</code>). Dies dient der modellbasierten Generierung technischer Dokumentationen, Spezifikationen, Tool-Hilfen (Context-Sensitive Help) und Traceability-Reports direkt aus AUTOSAR-Beschreibungsdateien (ARXML).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>DocumentationBlock</code> (<code>«atpMixed»</code>):</strong> Zentraler Container für formatierten Dokumentationsinhalt. Unterstützt Mixed-Content (Text gemischt mit Kind-Tags).\n</li><li><strong><code>List</code>:</strong> Standard-Aufzählungsliste (nummeriert oder unnummeriert).\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>type: ListEnum [0..1]</code> (definiert den Listenstil).\n</li></ul>\n</li><li><strong><code>«enumeration» ListEnum</code>:</strong> Aufzählungstyp für Listenformatierung mit den Literalen:\n<ul class=\"fig-list\"><li><code>number</code>: Nummerierte Liste.\n</li><li><code>unnumber</code>: Unnummerierte Aufzählungsliste (Bulletpoints).\n</li></ul>\n</li><li><strong><code>Item</code>:</strong> Einzelner Eintrag einer Standard-Liste.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>LabeledList</code>:</strong> Liste mit beschrifteten Einträgen (Schlagwortlisten / Term-Definitionen).\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>IndentSample</code>:</strong> Steuert Einrückung und Ausrichtung der Label-Einträge.\n<ul class=\"fig-list\"><li><em>Attribute:</em> <code>itemLabelPos: ItemLabelPosEnum [0..1]</code> (Positionierung des Labels).\n</li></ul>\n</li><li><strong><code>LabeledItem</code>:</strong> Eintrag einer <code>LabeledList</code>.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>helpEntry: String [0..1]</code> (Schlüssel für toolgestützte Hilfe/Tooltips).\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong> Mehrsprachiger Übersichtsabsatz für Labeltexte.\n</li><li><strong><code>LOverviewParagraph</code> (<code>«atpMixedString»</code>):</strong> Sprachspezifischer Textinhalt (<code>LanguageSpecific</code>, <code>MixedContentForOverviewParagraph</code>).\n<ul class=\"fig-list\"><li><em>Attribute:</em> <code>blueprintValue: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>DefList</code>:</strong> Definitionsliste für Glossare, Begriffsbestimmungen oder Parameterbeschreibungen.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>DefItem</code>:</strong> Spezifischer Begriffseintrag innerhalb einer Definitionsliste.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>MultilanguageReferrable</code> (erlaubt direkte Adressierung/Referenzierung über Sprachgrenzen hinweg via ShortName/Identifikator) und <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>helpEntry: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>Paginateable</code>:</strong> Basis-Abstraktion zur Steuerung von Umbrüchen (z. B. Seitenumbrüche, Zusammenhalten von Blöcken beim Dokumenten-Rendering).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten &amp; Variabilitäts-Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong>Variationsbindung:</strong> Alle primären Listen- und Item-Aggregationen tragen die Stereotypen <code>«atpVariation, atpSplitable»</code> mit dem Tag <code>vh.latestBindingTime = postBuild</code>.\n</li><li><strong>Listen-Aggregationen von <code>DocumentationBlock</code>:</strong>\n<ul class=\"fig-list\"><li><code>+list: List [0..1]</code> (<code>«atpVariation, atpSplitable»</code>)\n</li><li><code>+labeledList: LabeledList [0..1]</code> (<code>«atpVariation, atpSplitable»</code>)\n</li><li><code>+defList: DefList [0..1]</code> (<code>«atpVariation, atpSplitable»</code>)\n</li></ul>\n</li><li><strong>Item-Aggregationen:</strong>\n<ul class=\"fig-list\"><li><code>List</code> aggregiert <code>+item: Item [1..*]</code> (<code>«atpVariation, atpSplitable»</code>).\n</li><li><code>LabeledList</code> aggregiert <code>+labeledItem: LabeledItem [1..*]</code> (<code>«atpVariation, atpSplitable»</code>) sowie <code>+indentSample: IndentSample [0..1]</code>.\n</li><li><code>DefList</code> aggregiert <code>+defItem: DefItem [1..*]</code> (<code>«atpVariation, atpSplitable»</code>).\n</li></ul>\n</li><li><strong>Label-Struktur (<code>LabeledList</code>):</strong>\n<ul class=\"fig-list\"><li><code>IndentSample</code> aggregiert <code>+l2: LOverviewParagraph [1..*]</code>.\n</li><li><code>LabeledItem</code> aggregiert <code>+itemLabel: MultiLanguageOverviewParagraph [1]</code>, welcher wiederum <code>+l2: LOverviewParagraph [1..*]</code> aggregiert.\n</li></ul>\n</li><li><strong>Rekursive Inhaltsbeziehung (Inhaltskapselung via blaue Kompositionsreferenzen):</strong>\n<ul class=\"fig-list\"><li><code>Item</code> referenziert/kapselt <code>+itemContents: DocumentationBlock [1]</code>.\n</li><li><code>LabeledItem</code> referenziert/kapselt <code>+itemContents: DocumentationBlock [0..1]</code>.\n</li><li><code>DefItem</code> referenziert/kapselt <code>+def: DocumentationBlock [1]</code>.\n</li><li><em>Architektur-Konsequenz:</em> Ermöglicht beliebige Schachtelungstiefen (Listen innerhalb von Listenelementen, Tabellen oder Absätzen).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Natur:</strong> Als statische Strukturdefinition des M2-Metamodells existiert kein direktes Runtime-Verhalten (weder OS-Tasks, RTE-Events noch BSW-Callbacks wie Det/Dem).\n</li><li><strong>Metamodell-Instanziierung &amp; Auswertungslebenszyklus:</strong>\n<ol class=\"fig-list\"><li><em>Authoring &amp; Splitting:</em> Aufgrund von <code>«atpSplitable»</code> können Listenfragmente über mehrere physische ARXML-Dateien verteilt abgelegt und vom Tooling zusammengeführt werden.\n</li><li><em>Variantenauflösung:</em> Über <code>«atpVariation»</code> mit <code>vh.latestBindingTime = postBuild</code> können Listenelemente über Systemvariablen (<code>SwSysCond</code>) bis zur Post-Build-Phase bedingt eingebunden oder entfernt werden.\n</li><li><em>Dokumentengenerierung / Rendering:</em> Formatierungsprozessoren werten <code>Paginateable</code>, <code>itemLabelPos</code> und die Sprachselektoren (<code>LOverviewParagraph</code>) aus, um Zielartefakte (PDF, HTML, Hilfedateien) deterministisch zu erzeugen.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konformität &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li>Beim Erstellen von Modell-Dokumentationen (z. B. in Software Component Descriptions oder BSW-Modul-Dokumentationen) erfordert jedes <code>Item</code> zwingend eine Instanz von <code>DocumentationBlock</code> (<code>+itemContents [1]</code>).\n</li><li>Eine <code>DefList</code> erzwingt für jedes <code>DefItem</code> zwingend eine Definition (<code>+def [1]</code>).\n</li><li>Bei <code>LabeledItem</code> ist <code>+itemContents</code> optional (<code>[0..1]</code>), jedoch ist das Label (<code>+itemLabel [1]</code>) obligatorisch.\n</li></ul>\n</li><li><strong>Toolchain &amp; Generatoren:</strong>\n<ul class=\"fig-list\"><li>Code- und Dokumentationsgeneratoren müssen die Rekursion auflösen (<code>Item -&gt; DocumentationBlock -&gt; List -&gt; Item</code>).\n</li><li>Tool-Entwickler für Context-Sensitive Help können <code>helpEntry</code> auslesen, um UI-Elemente direkt mit den entsprechenden Glossar- oder Spezifikationsabschnitten zu verknüpfen.\n</li></ul>\n</li><li><strong>Cross-Referencing (<code>MultilanguageReferrable</code>):</strong>\n<ul class=\"fig-list\"><li><code>DefItem</code> besitzt Referenzierbarkeit über Modellgrenzen hinweg. Entwickler können formale Querverweise auf definierte Terme setzen, ohne sprachenabhängige IDs verwalten zu müssen.\n</li></ul>\n</li><li><strong>Embedded-Ressourcen:</strong> Keine direkten Flash/RAM-Footprint-Auswirkungen auf die Ziel-MCU; rein werkzeug- und generierungsrelevante Metadaten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ce23b0a0b8680f49", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation der Dokumentationsstrukturen innerhalb des <em>AUTOSAR Generic Structure Template</em> (TPS_GenericStructureTemplate, Kapitel 9 <em>Documentation</em>). Das Metamodell definiert die standardisierte ARXML-Repräsentation von Listenstrukturen (<code>List</code>, <code>LabeledList</code>, <code>DefList</code>) innerhalb von Dokumentationsblöcken (<code>DocumentationBlock</code>). Dies dient der modellbasierten Generierung technischer Dokumentationen, Spezifikationen, Tool-Hilfen (Context-Sensitive Help) und Traceability-Reports direkt aus AUTOSAR-Beschreibungsdateien (ARXML).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>DocumentationBlock</code> (<code>«atpMixed»</code>):</strong> Zentraler Container für formatierten Dokumentationsinhalt. Unterstützt Mixed-Content (Text gemischt mit Kind-Tags).\n</li><li><strong><code>List</code>:</strong> Standard-Aufzählungsliste (nummeriert oder unnummeriert).\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>type: ListEnum [0..1]</code> (definiert den Listenstil).\n</li></ul>\n</li><li><strong><code>«enumeration» ListEnum</code>:</strong> Aufzählungstyp für Listenformatierung mit dem Abschnitt <code>literals</code>:\n<ul class=\"fig-list\"><li><code>number</code>: Nummerierte Liste.\n</li><li><code>unnumber</code>: Unnummerierte Aufzählungsliste (Bulletpoints).\n</li></ul>\n</li><li><strong><code>Item</code>:</strong> Einzelner Eintrag einer Standard-Liste.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>LabeledList</code>:</strong> Liste mit beschrifteten Einträgen (Schlagwortlisten / Term-Definitionen).\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>IndentSample</code>:</strong> Steuert Einrückung und Ausrichtung der Label-Einträge.\n<ul class=\"fig-list\"><li><em>Attribute:</em> <code>itemLabelPos: ItemLabelPosEnum [0..1]</code> (Positionierung des Labels).\n</li></ul>\n</li><li><strong><code>LabeledItem</code>:</strong> Eintrag einer <code>LabeledList</code>.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>helpEntry: String [0..1]</code> (Schlüssel für toolgestützte Hilfe/Tooltips).\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong> Mehrsprachiger Übersichtsabsatz für Labeltexte.\n</li><li><strong><code>LOverviewParagraph</code> (<code>«atpMixedString»</code>):</strong> Sprachspezifischer Textinhalt (<code>LanguageSpecific</code>, <code>MixedContentForOverviewParagraph</code>).\n<ul class=\"fig-list\"><li><em>Attribute:</em> <code>blueprintValue: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>DefList</code>:</strong> Definitionsliste für Glossare, Begriffsbestimmungen oder Parameterbeschreibungen.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>Paginateable</code>.\n</li></ul>\n</li><li><strong><code>DefItem</code>:</strong> Spezifischer Begriffseintrag innerhalb einer Definitionsliste.\n<ul class=\"fig-list\"><li><em>Vererbung:</em> Spezialisiert <code>MultilanguageReferrable</code> (erlaubt direkte Adressierung/Referenzierung über Sprachgrenzen hinweg via ShortName/Identifikator) und <code>Paginateable</code>.\n</li><li><em>Attribute:</em> <code>helpEntry: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>Paginateable</code>:</strong> Basis-Abstraktion zur Steuerung von Umbrüchen (z. B. Seitenumbrüche, Zusammenhalten von Blöcken beim Dokumenten-Rendering).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten &amp; Variabilitäts-Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong>Variationsbindung:</strong> Alle primären Listen- und Item-Aggregationen tragen das Stereotyp <code>«atpVariation»</code> mit dem Tag <code>vh.latestBindingTime = postBuild</code>.\n</li><li><strong>Listen-Aggregationen von <code>DocumentationBlock</code>:</strong>\n<ul class=\"fig-list\"><li><code>+list: List [0..1]</code> (<code>«atpVariation»</code>)\n</li><li><code>+labeledList: LabeledList [0..1]</code> (<code>«atpVariation»</code>)\n</li><li><code>+defList: DefList [0..1]</code> (<code>«atpVariation»</code>)\n</li></ul>\n</li><li><strong>Item-Aggregationen:</strong>\n<ul class=\"fig-list\"><li><code>List</code> aggregiert <code>+item: Item [1..*]</code> (<code>«atpVariation»</code>).\n</li><li><code>LabeledList</code> aggregiert <code>+labeledItem: LabeledItem [1..*]</code> (<code>«atpVariation»</code>) sowie <code>+indentSample: IndentSample [0..1]</code>.\n</li><li><code>DefList</code> aggregiert <code>+defItem: DefItem [1..*]</code> (<code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong>Inhalts-Aggregationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>Item</code> besitzt eine unidirektionale Komposition <code>+itemContents</code> zu <code>DocumentationBlock [1]</code>.\n</li><li><code>LabeledList</code> aggregiert <code>+indentSample: IndentSample [0..1]</code>.\n</li><li><code>IndentSample</code> aggregiert <code>+l2: LOverviewParagraph [1..*]</code> über <code>MultiLanguageOverviewParagraph</code>.\n</li><li><code>LabeledItem</code> aggregiert <code>+itemLabel: MultiLanguageOverviewParagraph [1]</code> sowie <code>+itemContents: DocumentationBlock [0..1]</code>.\n</li><li><code>DefItem</code> aggregiert <code>+def: DocumentationBlock [1]</code> (Rollenname <code>+def</code>) und <code>+itemContents: DocumentationBlock [0..1]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Natur:</strong> Als statische Strukturdefinition des M2-Metamodells existiert kein direktes Runtime-Verhalten (weder OS-Tasks, RTE-Events noch BSW-Callbacks wie Det/Dem).\n</li><li><strong>Metamodell-Instanziierung &amp; Auswertungslebenszyklus:</strong>\n<ol class=\"fig-list\"><li><em>Authoring &amp; Splitting:</em> Aufgrund von <code>«atpSplitable»</code> können Listenfragmente über mehrere physische ARXML-Dateien verteilt abgelegt und vom Tooling zusammengeführt werden.\n</li><li><em>Variantenauflösung:</em> Über <code>«atpVariation»</code> mit <code>vh.latestBindingTime = postBuild</code> können Listenelemente über Systemvariablen (<code>SwSysCond</code>) bis zur Post-Build-Phase bedingt eingebunden oder entfernt werden.\n</li><li><em>Dokumentengenerierung / Rendering:</em> Formatierungsprozessoren werten <code>Paginateable</code>, <code>itemLabelPos</code> und die Sprachselektoren (<code>LOverviewParagraph</code>) aus, um Zielartefakte (PDF, HTML, Hilfedateien) deterministisch zu erzeugen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Konformität &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li>Beim Erstellen von Modell-Dokumentationen (z. B. in Software Component Descriptions oder BSW-Modul-Dokumentationen) erfordert jedes <code>Item</code> zwingend eine Instanz von <code>DocumentationBlock</code> (<code>+itemContents [1]</code>).\n</li><li>Eine <code>DefList</code> erzwingt für jedes <code>DefItem</code> zwingend eine Definition (<code>+def [1]</code>).\n</li><li>Bei <code>LabeledItem</code> ist <code>+itemContents</code> optional (<code>[0..1]</code>), jedoch ist das Label (<code>+itemLabel [1]</code>) obligatorisch.\n</li></ul>\n</li><li><strong>Toolchain &amp; Generatoren:</strong>\n<ul class=\"fig-list\"><li>Code- und Dokumentationsgeneratoren müssen die Rekursion auflösen (<code>Item -&gt; DocumentationBlock -&gt; List -&gt; Item</code>).\n</li><li>Tool-Entwickler für Context-Sensitive Help können <code>helpEntry</code> auslesen, um UI-Elemente direkt mit den entsprechenden Glossar- oder Spezifikationsabschnitten zu verknüpfen.\n</li></ul>\n</li><li><strong>Cross-Referencing (<code>MultilanguageReferrable</code>):</strong>\n<ul class=\"fig-list\"><li><code>DefItem</code> besitzt Referenzierbarkeit über Modellgrenzen hinweg. Entwickler können formale Querverweise auf definierte Terme setzen, ohne sprachenabhängige IDs verwalten zu müssen.\n</li></ul>\n</li><li><strong>Embedded-Ressourcen:</strong> Keine direkten Flash/RAM-Footprint-Auswirkungen auf die Ziel-MCU; rein werkzeug- und generierungsrelevante Metadaten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-58a642b11a613701", "to": "FIG-ce23b0a0b8680f49", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp <code>«atpSplitable»</code> an den Aggregationen <code>+list</code>, <code>+item</code>, <code>+labeledList</code>, <code>+labeledItem</code>, <code>+defList</code> und <code>+defItem</code> entfernt; diese sind nun ausschließlich mit <code>«atpVariation»</code> annotiert.\n</li><li>Enumeration <code>ListEnum</code>: Abschnittskopf <code>literals</code> oberhalb der Attribute/Literale ergänzt.\n</li></ul>"}]};
